def f(m, n):
    if m == 0 or n == 0:
        return 1
    return f(m - 1, n) + f(m - 1, n - 1) + f(m, n - 1)

print(f(3, 3))

def f(a, b):
    if a == 1:
        return 1
    return b * f(a - 1, b)

print(f(5, 3))
